package com.bank.deploy;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// SESSION mode: one long-lived cluster shared by many jobs (weak isolation, shared fate).
class SessionCluster {
    private static final Logger log = Logger.getLogger(SessionCluster.class.getName());

    private final int totalSlots;
    private int usedSlots = 0;
    private final List<String> runningJobs = new ArrayList<>();

    SessionCluster(int totalSlots) {
        this.totalSlots = totalSlots;
        log.info(() -> "Session cluster started with " + totalSlots + " shared slots (stays up)");
    }

    void submit(FlinkJob job) {
        if (usedSlots + job.requiredSlots > totalSlots) {
            log.warning(() -> "Job '" + job.name + "' WAITS: only " + (totalSlots - usedSlots)
                    + " shared slots free (contention with other jobs)");
            return;
        }
        usedSlots += job.requiredSlots;
        runningJobs.add(job.name);
        log.info(() -> "Submitted '" + job.name + "' to SHARED session cluster (fast start, no isolation)");
    }

    // A failure here can affect ALL jobs on the shared cluster.
    void taskManagerFailure() {
        log.severe(() -> "TaskManager failure in session cluster affects ALL running jobs: " + runningJobs);
    }
}
