package com.bank.deploy;

import java.util.logging.Logger;

// PER-JOB mode (deprecated): dedicated cluster per job, but main() runs on the CLIENT.
class PerJobDeployer {
    private static final Logger log = Logger.getLogger(PerJobDeployer.class.getName());

    void deploy(FlinkJob job) {
        log.warning(() -> "[Per-Job, DEPRECATED] Client builds JobGraph for '" + job.name
                + "' (main runs on CLIENT — client does heavy work, needs all deps)");
        log.info(() -> "[Per-Job] Dedicated cluster created for '" + job.name + "' with "
                + job.requiredSlots + " slots (isolated)");
        log.info(() -> "[Per-Job] Cluster torn down when '" + job.name + "' finishes");
        log.warning("[Per-Job] Submitting many jobs bottlenecks on the single client — prefer Application mode");
    }
}
