package com.bank.deploy;

import java.util.logging.Logger;

// APPLICATION mode (preferred): dedicated cluster per application, main() runs on the CLUSTER.
class ApplicationDeployer {
    private static final Logger log = Logger.getLogger(ApplicationDeployer.class.getName());

    void deploy(FlinkJob job) {
        log.info(() -> "[Application] Client ships jar for '" + job.name + "' and RETURNS immediately");
        log.info(() -> "[Application] main() runs ON THE CLUSTER (JobGraph built cluster-side, deps isolated)");
        log.info(() -> "[Application] Dedicated cluster per application with " + job.requiredSlots
                + " slots — full isolation" + (job.critical ? " (ideal for critical production)" : ""));
        log.info(() -> "[Application] Cluster lifecycle = exactly this application; cleaned up after");
    }
}
