package com.bank.deploy;

import java.util.logging.Logger;

public class DeployModesDemo {
    private static final Logger log = Logger.getLogger(DeployModesDemo.class.getName());

    public static void main(String[] args) {
        FlinkJob devJob = new FlinkJob("dev-exploration", 3, false);
        FlinkJob prodJob = new FlinkJob("realtime-fraud-scoring", 3, true);

        // SESSION mode: both share one cluster → contention + shared fate.
        log.info("=== SESSION mode (shared, for dev/interactive) ===");
        SessionCluster session = new SessionCluster(4);
        session.submit(devJob);     // takes 3 of 4 slots
        session.submit(prodJob);    // only 1 slot free → waits (contention!)
        session.taskManagerFailure(); // affects all jobs

        // PER-JOB mode: isolated per job, but main on client (deprecated).
        log.info("=== PER-JOB mode (deprecated) ===");
        new PerJobDeployer().deploy(prodJob);

        // APPLICATION mode: isolated per app, main on cluster (preferred for production).
        log.info("=== APPLICATION mode (preferred for production) ===");
        new ApplicationDeployer().deploy(prodJob);
    }
}
